package theme

import (
	"encoding/json"
	"image/color"
	"io"

	"fyne.io/fyne/v2"
)

// FromJSON creates a theme from JSON bytes.
// Returns an error if the JSON is invalid.
//
// Since: 2.5
func FromJSON(data []byte) (fyne.Theme, error) {
	var themeData map[string]interface{}
	if err := json.Unmarshal(data, &themeData); err != nil {
		return nil, err
	}
	return parseThemeData(themeData), nil
}

// FromJSONReader creates a theme by reading JSON from an io.Reader.
// Returns an error if the JSON is invalid or cannot be read.
//
// Since: 2.5
func FromJSONReader(reader io.Reader) (fyne.Theme, error) {
	var themeData map[string]interface{}
	decoder := json.NewDecoder(reader)
	if err := decoder.Decode(&themeData); err != nil {
		return nil, err
	}
	return parseThemeData(themeData), nil
}

type jsonTheme struct {
	colors map[string]map[string]color.Color
	sizes  map[string]float32
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	variantName := "light"
	if variant == fyne.VariantDark {
		variantName = "dark"
	}

	if colors, ok := t.colors[string(name)]; ok {
		if c, ok := colors[variantName]; ok {
			return c
		}
	}

	// Fallback to default theme
	return Default().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	// Fallback to default fonts
	return Default().Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	// Fallback to default icons
	return Default().Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[string(name)]; ok {
		return size
	}

	// Fallback to default theme
	return Default().Size(name)
}

func parseThemeData(data map[string]interface{}) fyne.Theme {
	theme := &jsonTheme{
		colors: make(map[string]map[string]color.Color),
		sizes:  make(map[string]float32),
	}

	// Parse colors
	if colorsData, ok := data["colors"].(map[string]interface{}); ok {
		for colorName, variantData := range colorsData {
			if variants, ok := variantData.(map[string]interface{}); ok {
				theme.colors[colorName] = make(map[string]color.Color)
				for variant, colorValue := range variants {
					if colorStr, ok := colorValue.(string); ok {
						if c := parseColor(colorStr); c != nil {
							theme.colors[colorName][variant] = c
						}
					}
				}
			}
		}
	}

	// Parse sizes
	if sizesData, ok := data["sizes"].(map[string]interface{}); ok {
		for sizeName, sizeValue := range sizesData {
			if size, ok := sizeValue.(float64); ok {
				theme.sizes[sizeName] = float32(size)
			}
		}
	}

	return theme
}

func parseColor(colorStr string) color.Color {
	// Simple hex color parser (#RRGGBB or #RRGGBBAA)
	if len(colorStr) < 7 || colorStr[0] != '#' {
		return nil
	}

	var r, g, b, a uint8
	a = 255

	if len(colorStr) == 7 {
		// #RRGGBB
		if _, err := parseHex(colorStr[1:3], &r); err != nil {
			return nil
		}
		if _, err := parseHex(colorStr[3:5], &g); err != nil {
			return nil
		}
		if _, err := parseHex(colorStr[5:7], &b); err != nil {
			return nil
		}
	} else if len(colorStr) == 9 {
		// #RRGGBBAA
		if _, err := parseHex(colorStr[1:3], &r); err != nil {
			return nil
		}
		if _, err := parseHex(colorStr[3:5], &g); err != nil {
			return nil
		}
		if _, err := parseHex(colorStr[5:7], &b); err != nil {
			return nil
		}
		if _, err := parseHex(colorStr[7:9], &a); err != nil {
			return nil
		}
	} else {
		return nil
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}
}

func parseHex(s string, v *uint8) (int, error) {
	var result uint8
	for i := 0; i < len(s); i++ {
		c := s[i]
		var digit uint8
		if c >= '0' && c <= '9' {
			digit = c - '0'
		} else if c >= 'a' && c <= 'f' {
			digit = c - 'a' + 10
		} else if c >= 'A' && c <= 'F' {
			digit = c - 'A' + 10
		} else {
			return 0, io.ErrUnexpectedEOF
		}
		result = result*16 + digit
	}
	*v = result
	return len(s), nil
}

