package binding

import (
	"fmt"
	"sync"
)

type sprintfBinding struct {
	base
	format string
	mu     sync.RWMutex
	values []DataItem
}

// NewSprintf creates a new string binding that formats its content using fmt.Sprintf.
// The format string is used with values from the provided data items.
// Changes to any of the source data items will trigger an update.
//
// Since: 2.5
func NewSprintf(format string, values ...DataItem) String {
	b := &sprintfBinding{
		format: format,
		values: values,
	}

	listener := NewDataListener(func() {
		b.trigger()
	})

	for _, v := range values {
		v.AddListener(listener)
	}

	return b
}

func (b *sprintfBinding) Get() (string, error) {
	b.mu.RLock()
	defer b.mu.RUnlock()

	args := make([]interface{}, len(b.values))
	for i, v := range b.values {
		switch val := v.(type) {
		case String:
			s, err := val.Get()
			if err != nil {
				return "", err
			}
			args[i] = s
		case Int:
			n, err := val.Get()
			if err != nil {
				return "", err
			}
			args[i] = n
		case Float:
			f, err := val.Get()
			if err != nil {
				return "", err
			}
			args[i] = f
		case Bool:
			bl, err := val.Get()
			if err != nil {
				return "", err
			}
			args[i] = bl
		default:
			// Try to extract value using reflection if needed
			args[i] = v
		}
	}

	return fmt.Sprintf(b.format, args...), nil
}

func (b *sprintfBinding) Set(string) error {
	// Sprintf bindings are read-only
	return nil
}

func (b *sprintfBinding) trigger() {
	b.mu.RLock()
	defer b.mu.RUnlock()
	b.base.trigger()
}

