// FromJSON creates a theme from JSON bytes.
// Returns an error if the JSON is invalid.
//
// Since: 2.5
func FromJSON(data []byte) (fyne.Theme, error) {
	var themeData map[string]interface{}
	if err := json.Unmarshal(data, &themeData); err != nil {
		return nil, err
	}
	return parseThemeData(themeData), nil
}

// FromJSONReader creates a theme from a JSON reader.
// Returns an error if the JSON is invalid.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	return FromJSON(data)
}

type jsonTheme struct {
	colors map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color
}

func parseThemeData(data map[string]interface{}) fyne.Theme {
	jt := &jsonTheme{
		colors: make(map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color),
	}

	if colorsData, ok := data["colors"].(map[string]interface{}); ok {
		for name, value := range colorsData {
			colorName := fyne.ThemeColorName(name)
			jt.colors[colorName] = make(map[fyne.ThemeVariant]color.Color)

			if colorStr, ok := value.(string); ok {
				// Single color for all variants
				c := parseColor(colorStr)
				jt.colors[colorName][VariantLight] = c
				jt.colors[colorName][VariantDark] = c
			} else if variants, ok := value.(map[string]interface{}); ok {
				// Different colors per variant
				if lightStr, ok := variants["light"].(string); ok {
					jt.colors[colorName][VariantLight] = parseColor(lightStr)
				}
				if darkStr, ok := variants["dark"].(string); ok {
					jt.colors[colorName][VariantDark] = parseColor(darkStr)
				}
			}
		}
	}

	return jt
}

func (jt *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	if variants, ok := jt.colors[name]; ok {
		if c, ok := variants[variant]; ok {
			return c
		}
	}
	return DefaultTheme().Color(name, variant)
}

func (jt *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	return DefaultTheme().Font(style)
}

func (jt *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	return DefaultTheme().Icon(name)
}

func (jt *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	return DefaultTheme().Size(name)
}

func parseColor(s string) color.Color {
	if len(s) == 0 {
		return color.Black
	}

	// Remove '#' prefix if present
	if s[0] == '#' {
		s = s[1:]
	}

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(s) {
	case 6: // RGB
		parseHex(s[0:2], &r)
		parseHex(s[2:4], &g)
		parseHex(s[4:6], &b)
	case 8: // RGBA
		parseHex(s[0:2], &r)
		parseHex(s[2:4], &g)
		parseHex(s[4:6], &b)
		parseHex(s[6:8], &a)
	case 3: // RGB short
		parseHex(s[0:1]+s[0:1], &r)
		parseHex(s[1:2]+s[1:2], &g)
		parseHex(s[2:3]+s[2:3], &b)
	case 4: // RGBA short
		parseHex(s[0:1]+s[0:1], &r)
		parseHex(s[1:2]+s[1:2], &g)
		parseHex(s[2:3]+s[2:3], &b)
		parseHex(s[3:4]+s[3:4], &a)
	default:
		return color.Black
	}

	return color.RGBA{R: r, G: g, B: b, A: a}
}

func parseHex(s string, v *uint8) (int, error) {
	var result uint8
	for i := 0; i < len(s); i++ {
		c := s[i]
		var digit uint8
		if c >= '0' && c <= '9' {
			digit = c - '0'
		} else if c >= 'a' && c <= 'f' {
			digit = c - 'a' + 10
		} else if c >= 'A' && c <= 'F' {
			digit = c - 'A' + 10
		} else {
			return 0, io.ErrUnexpectedEOF
		}
		result = result*16 + digit
	}
	*v = result
	return len(s), nil
}

