158|		} else if c >= 'a' && c <= 'f' {
159|			digit = c - 'a' + 10
160|		} else if c >= 'A' && c <= 'F' {
161|			digit = c - 'A' + 10
162|		} else {
163|			return 0, io.ErrUnexpectedEOF
164|		}
165|		result = result*16 + digit
166|	}
